/**
 * Combines street name parts into a single street name.
 *
 * @param {?string} name (e.g. Lawrence)
 * @param {?string} type (e.g. Ave)
 * @param {?string} dir (e.g. W)
 * @returns {string} combined street name (e.g. Lawrence Ave W), or `null`
 * if `name` is empty
 */
function formatStreetName(name, type, dir) {
  if (!name) {
    return null;
  }
  const parts = [name];
  if (type) {
    parts.push(type);
    if (dir) {
      parts.push(dir);
    }
  }
  return parts.map(part => part.trim()).join(' ');
}

