import db from '@/lib/db/db';
import { formatStreetName } from '@/lib/StringFormatters';

class CollisionDAO {
  static async byCentrelineSummary(
    centrelineId,
    centrelineType,
    dateRange,
  ) {
    const params = { centrelineId, centrelineType };
    const filters = [
      'ec.centreline_id = $(centrelineId)',
      'ec.centreline_type = $(centrelineType)',
    ];
    if (dateRange !== null) {
      Object.assign(params, dateRange);
      filters.push('e.accdate >= $(start)');
      filters.push('e.accdate < $(end)');
    }
    const sqlFilters = filters.join('\n  AND ');
    const sql = `
WITH collisions AS (
  SELECT i.collision_id, MAX(CONCAT('0', i.injury)::int) AS injury
  FROM collisions.events e
  JOIN collisions.involved i ON e.collision_id = i.collision_id
  JOIN collisions.events_centreline ec ON e.collision_id = ec.collision_id
  WHERE ${sqlFilters}
  GROUP BY i.collision_id
)
SELECT
COUNT(*) AS total,
COUNT(*) FILTER (WHERE injury >= 3) AS ksi
FROM collisions`;
    return db.one(sql, params);
  }

  /**
   * Groups the given age into a 5-year bucket, as a string.  This is used to
   * report the age of a person involved in a collision without exposing their
   * exact age.
   *
   * @param {?number} age - age, in years, of a person involved in a collision
   * @returns {?string} age range (e.g. `"30-34"`), or `null` if `age` is missing
   */
  static getAgeRange(age) {
    if (age === null || age === undefined) {
      return null;
    }
    if (age < 5) {
      return '0-4';
    }
    if (age >= 85) {
      return '85+';
    }
    const lower = age - (age % 5);
    return `${lower}-${lower + 4}`;
  }

  /**
   * Normalizes the rows returned for a single collision into the object returned
   * by {@link CollisionDAO.popupDetailsById}.
   *
   * @param {Object} rows - one row per involved person (or a single row with
   * `null` involved person fields if no persons are recorded)
   * @returns {Object} normalized popup details
   */
  static rowsToCollisionPopupDetails(rows) {
    const { id, accnb, accdate, acctime } = rows[0];
    const involved = [];
    let injury = 0;
    rows.forEach((row) => {
      if (row.invtype === null && row.invage === null) {
        return;
      }
      const personInjury = row.personInjury === null ? 0 : row.personInjury;
      injury = Math.max(injury, personInjury);
      involved.push({
        invtype: row.invtype,
        ageRange: CollisionDAO.getAgeRange(row.invage),
        injury: personInjury,
      });
    });
    return {
      id,
      accnb,
      accdate,
      acctime,
      injury,
      involved,
      street1: formatStreetName(rows[0].stname1, rows[0].streetype1, rows[0].dir1),
      street2: formatStreetName(rows[0].stname2, rows[0].streetype2, rows[0].dir2),
      street3: formatStreetName(rows[0].stname3, rows[0].streetype3, rows[0].dir3),
    };
  }

  /**
   * Fetches the details shown in the map popup for a single collision: the
   * accident number, date / time of occurrence, street names, and the persons
   * involved.
   *
   * @param {number} id - collision id, as used by the map layers
   * @returns {Object?} popup details for the given collision, or `null` if it
   * doesn't exist
   */
  static async popupDetailsById(id) {
    const params = { id };
    const sql = `
WITH event AS (
  SELECT
    e.collision_id,
    e.accnb,
    e.accdate::text AS accdate,
    e.acctime,
    e.stname1,
    e.streetype1,
    e.dir1,
    e.stname2,
    e.streetype2,
    e.dir2,
    e.stname3,
    e.streetype3,
    e.dir3
  FROM collisions.events e
  WHERE e.collision_id = $(id)
),
involved AS (
  SELECT
    i.collision_id,
    i.invtype,
    i.invage,
    CONCAT('0', i.injury)::int AS person_injury
  FROM collisions.involved i
  WHERE i.collision_id = $(id)
)
SELECT
  e.collision_id AS id,
  e.accnb,
  e.accdate,
  e.acctime,
  e.stname1,
  e.streetype1,
  e.dir1,
  e.stname2,
  e.streetype2,
  e.dir2,
  e.stname3,
  e.streetype3,
  e.dir3,
  i.invtype,
  i.invage,
  i.person_injury
FROM event e
LEFT JOIN involved i ON e.collision_id = i.collision_id`;
    const rows = await db.manyOrNone(sql, params);
    if (rows.length === 0) {
      return null;
    }
    return CollisionDAO.rowsToCollisionPopupDetails(rows);
  }
}

export default CollisionDAO;

